class Solution:
    def secondsBetween(self, startTime: str, endTime: str) -> int:
        def to_sec(t: str) -> int:
            h, m, s = t.split(':')
            return int(h) * 3600 + int(m) * 60 + int(s)
        return to_sec(endTime) - to_sec(startTime)

